#!/usr/bin/env node

// Lightweight host-side instantiation probe for the expander Wasm generated by
// probe-expander-full-compile.rkt. This deliberately does not call `entry` by
// default; the first milestone is checking that the generated module validates,
// links, and instantiates with the ordinary WebRacket host import shape.

import fs from 'node:fs';
import { spawn } from 'node:child_process';

function usage() {
  console.error('usage: node --experimental-wasm-exnref webify/probe-expander-instantiate.js <expander.wasm> [--call-entry] [--expect-entry-throws] [--list-names] [--ref NAME] [--call NAME] [--call-expect-printed NAME EXPECTED] [--call-json NAME JSON-ARGS] [--call-json-expect-printed NAME JSON-ARGS EXPECTED] [--bounded-call-json TIMEOUT-MS NAME JSON-ARGS] [--bounded-eval-matrix TIMEOUT-MS] [--read-string TEXT] [--read-syntax-string SOURCE TEXT] [--read-syntax-phase-string SOURCE TEXT] [--read-syntax-class-string SOURCE TEXT] [--read-syntax-class-matrix SOURCE] [--read-syntax-inspect-string SOURCE TEXT] [--read-syntax-inspect-matrix SOURCE] [--read-syntax-safe-datum-string SOURCE TEXT] [--read-syntax-safe-datum-matrix SOURCE] [--read-syntax-expander-datum-string SOURCE TEXT] [--read-syntax-expander-summary-string SOURCE TEXT] [--read-syntax-procedure-shape-string SOURCE TEXT] [--read-syntax-lang-parameterized-string SOURCE TEXT] [--read-syntax-datum-string SOURCE TEXT] [--read-syntax-summary-string SOURCE TEXT] [--parameterization-pressure COUNT]');
}

const args = process.argv.slice(2);
const wasmPath = args.find((arg) => !arg.startsWith('--'));
const callEntry = args.includes('--call-entry');
const expectEntryThrows = args.includes('--expect-entry-throws');
const listNames = args.includes('--list-names');
const refNames = [];
const callRequests = [];
const callJsonRequests = [];
const boundedCallJsonRequests = [];
const readStringRequests = [];
const readSyntaxStringRequests = [];
const readSyntaxPhaseStringRequests = [];
const readSyntaxClassStringRequests = [];
const readSyntaxInspectStringRequests = [];
const readSyntaxSafeDatumStringRequests = [];
const readSyntaxExpanderDatumStringRequests = [];
const readSyntaxExpanderSummaryStringRequests = [];
const readSyntaxProcedureShapeStringRequests = [];
const readSyntaxLangParameterizedStringRequests = [];
const readSyntaxDatumStringRequests = [];
const readSyntaxSummaryStringRequests = [];
const parameterizationPressureRequests = [];

const readSyntaxMatrixTexts = ['', ' ', '42', 'a', '()', '(a)', '#lang racket\n42'];

for (let i = 0; i < args.length; i++) {
  if (args[i] === '--ref') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    refNames.push(args[++i]);
  } else if (args[i] === '--call') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    callRequests.push({ name: args[++i] });
  } else if (args[i] === '--call-expect-printed') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    callRequests.push({
      name: args[++i],
      expectedPrinted: args[++i],
    });
  } else if (args[i] === '--call-json') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    callJsonRequests.push({
      name: args[++i],
      argsJson: args[++i],
    });
  } else if (args[i] === '--call-json-expect-printed') {
    if (i + 3 >= args.length) {
      usage();
      process.exit(2);
    }
    callJsonRequests.push({
      name: args[++i],
      argsJson: args[++i],
      expectedPrinted: args[++i],
    });
  } else if (args[i] === '--bounded-call-json') {
    if (i + 3 >= args.length) {
      usage();
      process.exit(2);
    }
    boundedCallJsonRequests.push({
      timeoutMs: Number(args[++i]),
      name: args[++i],
      argsJson: args[++i],
    });
  } else if (args[i] === '--bounded-eval-matrix') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    const timeoutMs = Number(args[++i]);
    for (const name of [
      'webify-probe-eval-self-evaluating',
      'webify-probe-eval-quoted-symbol',
      'webify-probe-eval-primitive-app',
      'webify-probe-eval-local-let',
    ]) {
      boundedCallJsonRequests.push({ timeoutMs, name, argsJson: '[]' });
    }
  } else if (args[i] === '--read-string') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    readStringRequests.push({ text: args[++i] });
  } else if (args[i] === '--read-syntax-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-phase-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxPhaseStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-class-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxClassStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-class-matrix') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    const source = args[++i];
    for (const text of readSyntaxMatrixTexts) {
      readSyntaxClassStringRequests.push({ source, text });
    }
  } else if (args[i] === '--read-syntax-inspect-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxInspectStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-inspect-matrix') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    const source = args[++i];
    for (const text of readSyntaxMatrixTexts) {
      readSyntaxInspectStringRequests.push({ source, text });
    }
  } else if (args[i] === '--read-syntax-safe-datum-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxSafeDatumStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-safe-datum-matrix') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    const source = args[++i];
    for (const text of readSyntaxMatrixTexts) {
      readSyntaxSafeDatumStringRequests.push({ source, text });
    }
  } else if (args[i] === '--read-syntax-expander-datum-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxExpanderDatumStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-expander-summary-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxExpanderSummaryStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-procedure-shape-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxProcedureShapeStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-lang-parameterized-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxLangParameterizedStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-datum-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxDatumStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--read-syntax-summary-string') {
    if (i + 2 >= args.length) {
      usage();
      process.exit(2);
    }
    readSyntaxSummaryStringRequests.push({
      source: args[++i],
      text: args[++i],
    });
  } else if (args[i] === '--parameterization-pressure') {
    if (i + 1 >= args.length) {
      usage();
      process.exit(2);
    }
    parameterizationPressureRequests.push(Number(args[++i]));
  }
}

if (!wasmPath) {
  usage();
  process.exit(2);
}

function hasNormalRequests() {
  return callEntry ||
    expectEntryThrows ||
    listNames ||
    refNames.length ||
    callRequests.length ||
    callJsonRequests.length ||
    readStringRequests.length ||
    readSyntaxStringRequests.length ||
    readSyntaxPhaseStringRequests.length ||
    readSyntaxClassStringRequests.length ||
    readSyntaxInspectStringRequests.length ||
    readSyntaxSafeDatumStringRequests.length ||
    readSyntaxExpanderDatumStringRequests.length ||
    readSyntaxExpanderSummaryStringRequests.length ||
    readSyntaxProcedureShapeStringRequests.length ||
    readSyntaxLangParameterizedStringRequests.length ||
    readSyntaxDatumStringRequests.length ||
    readSyntaxSummaryStringRequests.length ||
    parameterizationPressureRequests.length;
}

function runBoundedCallJson(request) {
  return new Promise((resolve) => {
    const label = `wr-bounded-call-json-${request.name}`;
    console.log(`${label}: start`);
    console.log(`${label}-timeout-ms: ${request.timeoutMs}`);
    const childArgs = [
      '--max-old-space-size=1024',
      '--experimental-wasm-exnref',
      new URL(import.meta.url).pathname,
      wasmPath,
      '--call-entry',
      '--call-json',
      request.name,
      request.argsJson,
    ];
    const child = spawn(process.execPath, childArgs, { stdio: ['ignore', 'pipe', 'pipe'] });
    let stdout = '';
    let stderr = '';
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill('SIGKILL');
    }, request.timeoutMs);
    child.stdout.on('data', (chunk) => {
      stdout += chunk.toString();
    });
    child.stderr.on('data', (chunk) => {
      stderr += chunk.toString();
    });
    child.on('close', (code, signal) => {
      clearTimeout(timer);
      if (timedOut) {
        console.log(`${label}-status: timeout`);
        console.log(`${label}-failure-category: bounded-timeout`);
      } else {
        console.log(`${label}-status: exited`);
        console.log(`${label}-exit-code: ${code}`);
        if (signal) {
          console.log(`${label}-signal: ${signal}`);
        }
      }
      const interesting = stdout
        .split(/\r?\n/)
        .filter((line) =>
          /probe:|budget-exhausted|current-procedure|debug-id|name|invocations|call-with-parameterization-wrapper-entry|call-with-parameterization-primitive-entry|application-not-procedure-frontier|binding-result-arity-frontier|procedure-arity-frontier|expected-count|received-count|got-struct-type|got-procedure|caller-name|caller-debug-id|argc|arg0-parameterization|arg1-procedure|arg1-name|arg1-debug-id|wr-call-json-|failure-category|failure-detail|FATAL ERROR|heap out of memory|entry-call/.test(line));
      for (const line of interesting.slice(-80)) {
        console.log(`${label}-child: ${line}`);
      }
      const errLines = stderr
        .split(/\r?\n/)
        .filter((line) => /FATAL ERROR|heap out of memory|Allocation failed|Error/.test(line));
      for (const line of errLines.slice(-20)) {
        console.log(`${label}-stderr: ${line}`);
      }
      if (timedOut || code !== 0) {
        process.exitCode = 1;
      }
      resolve();
    });
  });
}

if (boundedCallJsonRequests.length && !hasNormalRequests()) {
  for (const request of boundedCallJsonRequests) {
    await runBoundedCallJson(request);
  }
  process.exit(process.exitCode ?? 0);
}

if (typeof WebAssembly.Tag === 'undefined' || typeof WebAssembly.Exception === 'undefined') {
  throw new Error('WebRacket requires WebAssembly exception handling (Tag + Exception).');
}

const wasmBuffer = fs.readFileSync(wasmPath);
const module = new WebAssembly.Module(wasmBuffer);
const moduleImports = WebAssembly.Module.imports(module);
const moduleExports = WebAssembly.Module.exports(module);
const memory = new WebAssembly.Memory({ initial: 1024 });
const foreignErrorTag = new WebAssembly.Tag({ parameters: ['externref'] });
const externals = [];
const printedFaslValues = [];
const CALLBACK_BUFFER_BASE = 1052672;
const CALLBACK_BUFFER_LENGTH = 65536;

function readU32(arr, i) {
  return ((arr[i] << 24) | (arr[i + 1] << 16) |
          (arr[i + 2] << 8) | arr[i + 3]) >>> 0;
}

function faslToJsValue(arr, i = 0) {
  const tag = arr[i++];

  function u32() {
    const v = readU32(arr, i);
    i += 4;
    return v;
  }

  function readBytes() {
    const len = u32();
    const b = arr.slice(i, i + len);
    i += len;
    return b;
  }

  function readString() {
    return new TextDecoder().decode(readBytes());
  }

  switch (tag) {
    case 0: {
      const raw = u32();
      return [(raw << 2) >> 2, i];
    }
    case 1:
      return [String.fromCodePoint(u32()), i];
    case 2:
      return [Symbol.for(readString()), i];
    case 3:
      return [readString(), i];
    case 4:
      return [readBytes(), i];
    case 5:
      return [arr[i++] !== 0, i];
    case 6:
      return [null, i];
    case 7: {
      let car;
      let cdr;
      [car, i] = faslToJsValue(arr, i);
      [cdr, i] = faslToJsValue(arr, i);
      return [{ tag: 'pair', car, cdr }, i];
    }
    case 8: {
      const n = u32();
      const vec = new Array(n);
      for (let j = 0; j < n; j++) {
        [vec[j], i] = faslToJsValue(arr, i);
      }
      return [vec, i];
    }
    case 9: {
      const hi = u32();
      const lo = u32();
      const dv = new DataView(new ArrayBuffer(8));
      dv.setUint32(0, hi);
      dv.setUint32(4, lo);
      return [dv.getFloat64(0), i];
    }
    case 10:
      return [undefined, i];
    case 11:
      return ['<eof>', i];
    case 12:
      return [externals[u32()], i];
    default:
      throw new Error(`bad FASL tag ${tag}`);
  }
}

function jsValueToFasl(v) {
  const out = [];
  const enc = new TextEncoder();

  function writeByte(b) {
    out.push(b & 0xff);
  }

  function writeU32(u) {
    out.push((u >>> 24) & 0xff,
             (u >>> 16) & 0xff,
             (u >>> 8) & 0xff,
             u & 0xff);
  }

  function writeBytes(u8) {
    writeU32(u8.length >>> 0);
    for (let i = 0; i < u8.length; i++) {
      writeByte(u8[i]);
    }
  }

  function writeString(s) {
    writeBytes(enc.encode(s));
  }

  function writeF64(x) {
    const dv = new DataView(new ArrayBuffer(8));
    dv.setFloat64(0, x, false);
    writeU32(dv.getUint32(0, false));
    writeU32(dv.getUint32(4, false));
  }

  function writeAny(x) {
    if (typeof x === 'number') {
      if (Number.isInteger(x) && x >= -(1 << 29) && x <= ((1 << 29) - 1)) {
        writeByte(0);
        writeU32((x & 0x3fffffff) >>> 0);
      } else {
        writeByte(9);
        writeF64(x);
      }
    } else if (typeof x === 'boolean') {
      writeByte(5);
      writeByte(x ? 1 : 0);
    } else if (x === null) {
      writeByte(6);
    } else if (x === undefined) {
      writeByte(10);
    } else if (x === '<eof>' || (x && x.tag === 'eof')) {
      writeByte(11);
    } else if (x && x.tag === 'char') {
      const cp = typeof x.cp === 'number' ? x.cp
               : typeof x.ch === 'string' ? x.ch.codePointAt(0)
               : undefined;
      if (cp === undefined) {
        throw new TypeError('bad char object');
      }
      writeByte(1);
      writeU32(cp >>> 0);
    } else if (x && x.tag === 'pair') {
      writeByte(7);
      writeAny(x.car);
      writeAny(x.cdr);
    } else if (x instanceof Uint8Array) {
      writeByte(4);
      writeBytes(x);
    } else if (Array.isArray(x)) {
      writeByte(8);
      writeU32(x.length >>> 0);
      for (const elem of x) {
        writeAny(elem);
      }
    } else if (typeof x === 'symbol') {
      writeByte(2);
      writeString(Symbol.keyFor(x) ?? x.description ?? '');
    } else if (typeof x === 'string') {
      writeByte(3);
      writeString(x);
    } else {
      const idx = externals.push(x) - 1;
      writeByte(12);
      writeU32(idx >>> 0);
    }
  }

  writeAny(v);
  return Uint8Array.from(out);
}

function probeJsonToJsValue(v) {
  if (Array.isArray(v)) {
    return v.map(probeJsonToJsValue);
  }
  if (!v || typeof v !== 'object') {
    return v;
  }
  if (Object.hasOwn(v, '$symbol')) {
    return Symbol.for(String(v.$symbol));
  }
  if (Object.hasOwn(v, '$char')) {
    return { tag: 'char', ch: String(v.$char) };
  }
  if (Object.hasOwn(v, '$eof')) {
    return '<eof>';
  }
  if (Object.hasOwn(v, '$pair')) {
    if (!Array.isArray(v.$pair) || v.$pair.length !== 2) {
      throw new TypeError('$pair must hold a two-element array');
    }
    return {
      tag: 'pair',
      car: probeJsonToJsValue(v.$pair[0]),
      cdr: probeJsonToJsValue(v.$pair[1]),
    };
  }
  if (Object.hasOwn(v, '$list')) {
    if (!Array.isArray(v.$list)) {
      throw new TypeError('$list must hold an array');
    }
    let result = null;
    for (let i = v.$list.length - 1; i >= 0; i--) {
      result = {
        tag: 'pair',
        car: probeJsonToJsValue(v.$list[i]),
        cdr: result,
      };
    }
    return result;
  }
  const out = {};
  for (const [key, value] of Object.entries(v)) {
    out[key] = probeJsonToJsValue(value);
  }
  return out;
}

function formatJsValue(v) {
  if (typeof v === 'symbol') {
    return Symbol.keyFor(v) ?? v.description ?? v.toString();
  }
  if (v && v.tag === 'path') {
    return `#<${v.prefix}:${v.bytes}>`;
  }
  if (v && v.tag === 'hash') {
    if (v.entries.length === 0) {
      return `${v.prefix}()`;
    }
    return `${v.prefix}(${v.entries.map(formatJsValue).join(' ')})`;
  }
  if (v && v.tag === 'opaque') {
    return `#<${v.name}>`;
  }
  if (v instanceof Uint8Array) {
    return `#<bytes ${v.length}>`;
  }
  if (Array.isArray(v)) {
    return `[${v.map(formatJsValue).join(', ')}]`;
  }
  if (v && v.tag === 'pair') {
    return `(${formatJsValue(v.car)} . ${formatJsValue(v.cdr)})`;
  }
  return String(v);
}

function parsePrintedPathValue(text) {
  const pathPattern = /^#<((?:unix-|windows-)?path):([^>]*)>$/;

  function parsePath(token) {
    const match = pathPattern.exec(token);
    return match ? { tag: 'path', prefix: match[1], bytes: match[2] } : null;
  }

  const direct = parsePath(text);
  if (direct) {
    return direct;
  }

  if (!text.startsWith('(') || !text.endsWith(')')) {
    return null;
  }

  const inner = text.slice(1, -1).trim();
  if (inner === '') {
    return [];
  }
  const tokens = inner.match(/#<(?:unix-|windows-)?path:[^>]*>/g);
  if (!tokens || tokens.join(' ') !== inner) {
    return null;
  }
  return tokens.map(parsePath);
}

function parsePrintedHashValue(text) {
  const match = /^(#(?:hash|hasheq|hasheqv|hashalw))\((.*)\)$/.exec(text);
  if (!match) {
    return null;
  }
  const body = match[2].trim();
  if (body !== '') {
    return null;
  }
  return { tag: 'hash', prefix: match[1], entries: [] };
}

function parsePrintedOpaqueValue(text) {
  const match = /^#<([A-Za-z0-9_.:/-]+)>$/.exec(text);
  return match ? { tag: 'opaque', name: match[1] } : null;
}

function parsePrintedNonFaslValue(text) {
  return parsePrintedPathValue(text)
      ?? parsePrintedHashValue(text)
      ?? parsePrintedOpaqueValue(text);
}

function bridgeInvoke(exported, payload) {
  const fasl = jsValueToFasl(payload);
  if (fasl.length > CALLBACK_BUFFER_LENGTH) {
    throw new RangeError('probe FASL payload exceeds callback buffer');
  }
  new Uint8Array(memory.buffer).set(fasl, CALLBACK_BUFFER_BASE);
  const len = exported(CALLBACK_BUFFER_BASE);
  const bytes = new Uint8Array(memory.buffer, CALLBACK_BUFFER_BASE, len);
  return faslToJsValue(bytes)[0];
}

function decodeBridgeResult(raw, operation, name) {
  if (!Array.isArray(raw) || raw.length < 5) {
    return {
      ok: false,
      kind: 'invalid-bridge-result',
      value: raw,
      printed: '',
      error: `invalid bridge result from ${operation}`,
    };
  }
  const [ok, kind, value, printed, error] = raw;
  const formattedKind = formatJsValue(kind);
  const formattedPrinted = typeof printed === 'string' ? printed : formatJsValue(printed);
  const formattedError = typeof error === 'string' ? error : formatJsValue(error);
  const nonFaslPrefix =
    'The callback attempted to return a WebRacket value with no JavaScript equivalent (i.e. without a FASL encoding): ';
  if (!ok && formattedKind === 'non-fasl-result' && formattedError.startsWith(nonFaslPrefix)) {
    const resultText = formattedError.slice(nonFaslPrefix.length);
    const printedValue = parsePrintedNonFaslValue(resultText);
    if (printedValue) {
      return {
        ok: true,
        kind: `printed-${printedValue.tag}-result`,
        value: printedValue,
        printed: resultText,
        error: '',
        operation,
        name,
      };
    }
  }
  return {
    ok: !!ok,
    kind: formattedKind,
    value,
    printed: formattedPrinted,
    error: formattedError,
    operation,
    name,
  };
}

function classifyBridgeFailure(result) {
  const text = `${result.kind}\n${result.printed}\n${result.error}`;

  if (/\bport-read-handler\b/.test(text)) {
    return {
      category: 'missing-port-read-handler',
      detail: 'reader reached port-read-handler before the runtime provided enough support',
    };
  }
  const readerParameterMatch = /\b(?:read-accept-[A-Za-z0-9-]+|read-case-sensitive)\b/.exec(text);
  if (readerParameterMatch) {
    return {
      category: 'missing-reader-parameter',
      detail: readerParameterMatch[0],
    };
  }
  if (result.kind === 'non-fasl-result' && /#<syntax[:>]/.test(text)) {
    return {
      category: 'non-fasl-syntax-result',
      detail: 'read-syntax returned a syntax-shaped value that the JS bridge cannot FASL-decode yet',
    };
  }
  if (/syntax->datum: contract violation[\s\S]*expected: syntax\?[\s\S]*given: #<syntax[:>]/.test(text)) {
    return {
      category: 'syntax-object-representation-mismatch',
      detail: 'read-syntax produced a syntax-shaped value that WebRacket syntax? does not recognize',
    };
  }
  const exnVariableMatch = /#\(struct exn:fail:contract:variable\b.*\s([^\s)]+)\)$/.exec(result.printed);
  if (exnVariableMatch) {
    return {
      category: 'unbound-variable',
      detail: exnVariableMatch[1],
    };
  }
  const unboundMatch = /(?:unbound|undefined|reference to undefined identifier)[^A-Za-z0-9_.-]*([A-Za-z0-9_.:/?+*<>=!-]+)/i.exec(text);
  if (unboundMatch) {
    return {
      category: 'unbound-variable',
      detail: unboundMatch[1],
    };
  }
  return {
    category: 'bridge-call-failure',
    detail: result.error || result.printed || result.kind,
  };
}

function printBridgeResult(label, result) {
  console.log(`${label}-status: ${result.ok ? 'ok' : 'failed'}`);
  console.log(`${label}-kind: ${result.kind}`);
  if (result.ok) {
    console.log(`${label}-value: ${formatJsValue(result.value)}`);
  } else {
    const failure = classifyBridgeFailure(result);
    console.log(`${label}-failure-category: ${failure.category}`);
    console.log(`${label}-failure-detail: ${failure.detail}`);
  }
  if (result.printed) {
    console.log(`${label}-printed: ${result.printed}`);
  }
  if (result.error) {
    console.log(`${label}-error: ${result.error}`);
  }
}

function printThrown(label, err) {
  console.log(`${label}: threw`);
  console.log(`${label}-exception-kind: ${err?.constructor?.name ?? typeof err}`);
  console.log(`${label}-wasm-exception?: ${err instanceof WebAssembly.Exception}`);
  if (err instanceof WebAssembly.Exception) {
    console.log(`${label}-foreign-exception?: ${err.is?.(foreignErrorTag) ?? false}`);
    if (err.is?.(foreignErrorTag)) {
      console.log(`${label}-foreign-exception-arg0: ${err.getArg(foreignErrorTag, 0)}`);
    } else if (label.startsWith('wr-read-syntax-string-')) {
      console.log(`${label}-failure-category: raw-read-syntax-wasm-exception`);
      console.log(`${label}-failure-detail: raw syntax-object result threw before bridge decoding; use --read-syntax-datum-string to expose the next runtime dependency`);
    } else {
      console.log(`${label}-failure-category: wasm-exception`);
      console.log(`${label}-failure-detail: unclassified wasm exception`);
    }
  }
  if (err?.stack) {
    console.log(err.stack);
  }
}

function printFasl(start, len) {
  const bytes = new Uint8Array(memory.buffer).slice(start, start + len);
  try {
    const [value] = faslToJsValue(bytes);
    const formatted = formatJsValue(value);
    printedFaslValues.push(formatted);
    console.log(`js_print_fasl: ${formatted}`);
  } catch (err) {
    console.log(`js_print_fasl: <decode-failed ${err.message}; ${len} bytes>`);
  }
}

function classifyPrintedFailure() {
  for (const text of printedFaslValues) {
    const variableMatch =
      /^#\(struct exn:fail:contract:variable\b.*\s([^\s)]+)\)$/.exec(text);
    if (variableMatch) {
      return {
        category: 'unbound-variable',
        detail: variableMatch[1],
      };
    }
  }
  return {
    category: 'unknown',
    detail: printedFaslValues.length === 0
      ? 'no printed FASL diagnostics'
      : printedFaslValues[printedFaslValues.length - 1],
  };
}

function primitiveImport(name) {
  switch (name) {
    case 'foreign_error_tag':
      return foreignErrorTag;
    case 'js_print_fasl':
      return printFasl;
    case 'register_external':
      return (obj) => {
        externals.push(obj);
        return externals.length - 1;
      };
    case 'lookup_external':
      return (idx) => externals[idx];
    case 'flonum_to_string':
      return () => 0;
    case 'char_foldcase':
      return (cp) => cp;
    case 'char_alphabetic':
    case 'char_numeric':
      return () => 0;
    default:
      return () => 0;
  }
}

const imports = {};
for (const spec of moduleImports) {
  if (!imports[spec.module]) {
    imports[spec.module] = {};
  }

  if (spec.module === 'env' && spec.name === 'memory') {
    imports[spec.module][spec.name] = memory;
  } else if (spec.module === 'math' && spec.name in Math) {
    imports[spec.module][spec.name] = Math[spec.name].bind(Math);
  } else if (spec.module === 'primitives') {
    imports[spec.module][spec.name] = primitiveImport(spec.name);
  } else if (spec.kind === 'function') {
    imports[spec.module][spec.name] = () => 0;
  }
}

console.log(`wasm-path: ${wasmPath}`);
console.log(`imports: ${moduleImports.length}`);
for (const spec of moduleImports) {
  console.log(`  ${spec.module}.${spec.name} : ${spec.kind}`);
}
console.log(`exports: ${moduleExports.length}`);

const instance = new WebAssembly.Instance(module, imports);
console.log('instantiate-status: ok');
console.log(`entry-kind: ${typeof instance.exports.entry}`);
console.log(`wr-names-kind: ${typeof instance.exports['wr-names']}`);

if (callEntry) {
  console.log('entry-call: start');
  try {
    instance.exports.entry();
    console.log('entry-call: ok');
    if (expectEntryThrows) {
      console.log('entry-call-expectation: expected throw, got ok');
      process.exitCode = 1;
    }
  } catch (err) {
    printThrown('entry-call', err);
    const failure = classifyPrintedFailure();
    console.log(`entry-failure-category: ${failure.category}`);
    console.log(`entry-failure-detail: ${failure.detail}`);
    if (expectEntryThrows) {
      console.log('entry-call-expectation: expected throw');
    } else {
      process.exitCode = 1;
    }
  }
}

if (listNames) {
  console.log('wr-names-call: start');
  try {
    const len = instance.exports['wr-names'](0);
    const [names] = faslToJsValue(new Uint8Array(memory.buffer, CALLBACK_BUFFER_BASE, len));
    console.log('wr-names-call: ok');
    console.log(`wr-names-count: ${Array.isArray(names) ? names.length : 'not-a-vector'}`);
    console.log(`wr-names-value: ${formatJsValue(names)}`);
  } catch (err) {
    printThrown('wr-names-call', err);
    process.exitCode = 1;
  }
}

for (const name of refNames) {
  const label = `wr-ref-${name}`;
  console.log(`${label}: start`);
  try {
    const result = decodeBridgeResult(
      bridgeInvoke(instance.exports['wr-ref'], name),
      'ref',
      name);
    printBridgeResult(label, result);
    if (!result.ok) {
      process.exitCode = 1;
    }
  } catch (err) {
    printThrown(label, err);
    process.exitCode = 1;
  }
}

for (const request of callRequests) {
  const label = `wr-call-${request.name}`;
  console.log(`${label}: start`);
  try {
    const result = decodeBridgeResult(
      bridgeInvoke(instance.exports['wr-call'], [request.name, []]),
      'call',
      request.name);
    printBridgeResult(label, result);
    if (request.expectedPrinted !== undefined) {
      if (result.printed === request.expectedPrinted) {
        console.log(`${label}-expect-printed: ok`);
      } else {
        console.log(`${label}-expect-printed: failed`);
        console.log(`${label}-expected-printed: ${request.expectedPrinted}`);
        process.exitCode = 1;
      }
    }
    if (!result.ok) {
      process.exitCode = 1;
    }
  } catch (err) {
    printThrown(label, err);
    process.exitCode = 1;
  }
}

for (const request of callJsonRequests) {
  const label = `wr-call-json-${request.name}`;
  console.log(`${label}: start`);
  try {
    const parsedArgs = JSON.parse(request.argsJson);
    if (!Array.isArray(parsedArgs)) {
      throw new TypeError('--call-json arguments must decode to a JSON array');
    }
    const probeArgs = parsedArgs.map(probeJsonToJsValue);
    const result = decodeBridgeResult(
      bridgeInvoke(instance.exports['wr-call'], [request.name, probeArgs]),
      'call-json',
      request.name);
    printBridgeResult(label, result);
    if (request.expectedPrinted !== undefined) {
      if (result.printed === request.expectedPrinted) {
        console.log(`${label}-expect-printed: ok`);
      } else {
        console.log(`${label}-expect-printed: failed`);
        console.log(`${label}-expected-printed: ${request.expectedPrinted}`);
        process.exitCode = 1;
      }
    }
    if (!result.ok) {
      process.exitCode = 1;
    }
  } catch (err) {
    printThrown(label, err);
    process.exitCode = 1;
  }
}

function runProbeHelper(label, name, probeArgs) {
  console.log(`${label}: start`);
  try {
    const result = decodeBridgeResult(
      bridgeInvoke(instance.exports['wr-call'], [name, probeArgs]),
      'call-json',
      name);
    printBridgeResult(label, result);
    if (!result.ok) {
      process.exitCode = 1;
    }
  } catch (err) {
    printThrown(label, err);
    process.exitCode = 1;
  }
}

for (const request of readStringRequests) {
  runProbeHelper(
    `wr-read-string-${JSON.stringify(request.text)}`,
    'webify-probe-read-string',
    [request.text]);
}

